Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <cstring>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;
using lint = long long;
lint binom[62][62], gridA[32][32], gridB[32][32];
int rows, cols, seqLen;
char rules[110];
lint totalWays;
lint smallestDelta;
lint answerCount;
lint memo[32][32];
vector<pair<lint,lint>> storeA[32][2], storeB[32][2];

void populate(int i, int j, lint val, lint w1, lint w2, bool flip) {
    if (i + j == seqLen) {
        storeA[i][flip].emplace_back(val, w1);
        if (w2) storeB[i][flip].emplace_back(val, w2);
        return;
    }
    populate(i+1, j, val + (!flip ? gridA[i+1][j] : 0), w1, (rules[i+j] != 'B' ? w2 : 0), flip);
    populate(i, j+1, val + (flip ? gridB[i][j+1] : 0), w1, (rules[i+j] != 'A' ? w2 : 0), flip);
}

void forwardWalk(int i, int j, lint cur, bool flip) {
    if (i + j == seqLen) {
        if (storeA[i][flip].empty()) return;
        auto it = lower_bound(storeA[i][flip].begin(), storeA[i][flip].end(), make_pair((totalWays+1)/2 - cur, 0LL));
        if (it != storeA[i][flip].end() && it->second > 0) {
            lint delta = abs((it->first + cur) * 2 - totalWays);
            if (delta < smallestDelta) smallestDelta = delta;
        }
        if (it != storeA[i][flip].begin()) {
            --it;
            if (it->second > 0) {
                lint delta = abs((it->first + cur) * 2 - totalWays);
                if (delta < smallestDelta) smallestDelta = delta;
            }
        }
        return;
    }
    if (i > 0) forwardWalk(i-1, j, cur + (!flip ? gridA[i][j] : 0), flip);
    if (j > 0) forwardWalk(i, j-1, cur + (flip ? gridB[i][j] : 0), flip);
}

void backwardWalk(int i, int j, lint cur, bool flip) {
    if (i + j == seqLen) {
        auto it = lower_bound(storeB[i][flip].begin(), storeB[i][flip].end(), make_pair((totalWays+1)/2 - cur, 0LL));
        if (it != storeB[i][flip].end() && it->second > 0) {
            lint delta = abs((it->first + cur) * 2 - totalWays);
            if (delta == smallestDelta) answerCount += it->second;
        }
        if (it != storeB[i][flip].begin()) {
            --it;
            if (it->second > 0) {
                lint delta = abs((it->first + cur) * 2 - totalWays);
                if (delta == smallestDelta) answerCount += it->second;
            }
        }
        return;
    }
    if (i > 0 && rules[i+j-1] != 'B') backwardWalk(i-1, j, cur + (!flip ? gridA[i][j] : 0), flip);
    if (j > 0 && rules[i+j-1] != 'A') backwardWalk(i, j-1, cur + (flip ? gridB[i][j] : 0), flip);
}

void dedup(vector<pair<lint,lint>>& v) {
    if (v.empty()) return;
    sort(v.begin(), v.end());
    lint accumulated = 0;
    vector<pair<lint,lint>> out;
    for (size_t k = 0; k < v.size(); ++k) {
        accumulated += v[k].second;
        if (k+1 == v.size() || v[k].first != v[k+1].first) {
            out.push_back({v[k].first, accumulated});
            accumulated = 0;
        }
    }
    v = out;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> rows >> cols;
    cin >> rules;
    for (int i = 0; i <= 60; ++i) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
    }
    seqLen = rows + cols;
    totalWays = binom[seqLen*2][rows*2];
    for (int i = 0; i <= seqLen; ++i)
        for (int j = 0; j <= seqLen; ++j) {
            if (i) gridA[i][j] = binom[i-1][rows-1] * (binom[seqLen*2-i][rows] - binom[j][rows]);
            if (j) gridB[i][j] = binom[j-1][rows-1] * (binom[seqLen*2-j][rows] - binom[i][rows]);
        }
    memo[0][0] = 1;
    for (int i = 0; i <= seqLen; ++i)
        for (int j = 0; j <= seqLen; ++j) {
            if (i < seqLen && rules[i+j] != 'B') memo[i+1][j] += memo[i][j];
            if (j < seqLen && rules[i+j] != 'A') memo[i][j+1] += memo[i][j];
        }
    for (int k = rows; k <= seqLen; ++k) {
        if (rules[k+rows-1] != 'B') populate(rows, k, gridA[rows][k], binom[k+rows-1][rows-1], memo[rows-1][k], 0);
        if (rules[k+rows-1] != 'A') populate(k, rows, gridB[k][rows], binom[k+rows-1][rows-1], memo[k][rows-1], 1);
    }
    for (int i = rows; i <= seqLen; ++i)
        for (int d = 0; d < 2; ++d) {
            dedup(storeA[i][d]);
            dedup(storeB[i][d]);
        }
    smallestDelta = totalWays + 1;
    forwardWalk(seqLen, seqLen, 0, 0);
    forwardWalk(seqLen, seqLen, 0, 1);
    backwardWalk(seqLen, seqLen, 0, 0);
    backwardWalk(seqLen, seqLen, 0, 1);
    cout << answerCount << '\n';
}
